// В n8n входные данные — массив items
// Каждый item.json должен содержать ключ text

const stopWords = [
  "и", "в", "во", "не", "что", "он", "на", "я", "с", "со",
  "как", "а", "то", "все", "она", "так", "его", "но", "да",
  "ты", "к", "у", "же", "вы", "за", "бы", "по", "ее", "мне",
  "было", "вот", "от", "меня", "еще", "нет", "о", "из", "ему",
  "теперь", "когда", "даже", "ну", "вдруг", "ли", "если", "уже",
  "или", "ни", "быть", "был", "него", "до", "вас", "нибудь",
  "опять", "уж", "вам", "ведь", "там", "потом", "себя", "ничего",
  "ей", "может", "они", "тут", "где", "есть", "надо", "ней",
  "для", "мы", "тебя", "их", "чем", "была", "сам", "чтоб",
  "без", "будто", "чего", "раз", "тоже", "себе", "под", "будет",
  "ж", "тогда", "кто", "этот", "того", "потому", "этого"
];

// Преобразуем каждый item
return items.map(item => {
  let text = item.json.text;

  if (!text) {
    item.json.normalizedText = "";
    return item;
  }

  // 1. Приведение к нижнему регистру
  text = text.toLowerCase();

  // 2. Удаление спецсимволов (оставим буквы, цифры и пробелы)
  text = text.replace(/[^а-яёa-z0-9\s]/gi, ' ');

  // 3. Замена нескольких пробелов на один
  text = text.replace(/\s+/g, ' ').trim();

  // 4. Удаление стоп-слов
  text = text.split(' ').filter(word => !stopWords.includes(word)).join(' ');

  item.json.normalizedText = text;

  return item;
});
